CREATE OR REPLACE FUNCTION public.prevent_activity_log_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'activity history is immutable'; END; $$; DROP TRIGGER IF EXISTS activity_log_immutable ON public.activity_logs; CREATE TRIGGER activity_log_immutable BEFORE UPDATE OR DELETE ON public.activity_logs FOR EACH ROW EXECUTE FUNCTION public.prevent_activity_log_mutation();